import { describe, expect, it } from "vitest";
import { cleanReadme } from "@/lib/github/readme";

describe("cleanReadme", () => {
  it("strips badges, images, HTML comments and raw HTML while keeping markdown structure", () => {
    const readme = [
      "<!-- generated by a template -->",
      "<p align=\"center\">",
      "  <img src=\"docs/logo.png\" width=\"120\"",
      "       alt=\"Logo\">",
      "</p>",
      "",
      "# BlastRadius",
      "[![CI](https://img.shields.io/ci.svg)](https://github.com/o/r/actions) [![License: MIT][license-badge]][license]",
      "",
      "Maps a codebase into a <b>dependency graph</b>.<br>Fast &amp; local.",
      "",
      "![Screenshot](docs/screenshot.png)",
      "",
      "## Features",
      "",
      "- Reads the [setup guide](docs/setup.md) and the [docs site](https://example.com/docs)",
      "- Uses `<Graph />` from the `[ui](lib)` package",
      "",
      "[license-badge]: https://img.shields.io/badge/license-MIT.svg",
      "[license]: LICENSE"
    ].join("\r\n");

    expect(cleanReadme(readme)).toBe(
      [
        "# BlastRadius",
        "",
        "Maps a codebase into a dependency graph. Fast & local.",
        "",
        "## Features",
        "",
        "- Reads the setup guide and the [docs site](https://example.com/docs)",
        "- Uses `<Graph />` from the `[ui](lib)` package"
      ].join("\n")
    );
  });

  it("keeps fenced code untouched, including comment lines and HTML", () => {
    const readme = [
      "## Install",
      "",
      "```bash",
      "# clone the repo",
      "",
      "",
      "",
      "npm install   ",
      "```",
      "",
      "~~~html",
      "<!-- keep me -->",
      "<img src=\"x.png\">",
      "~~~"
    ].join("\n");

    expect(cleanReadme(readme)).toBe(
      [
        "## Install",
        "",
        "```bash",
        "# clone the repo",
        "",
        "",
        "",
        "npm install",
        "```",
        "",
        "~~~html",
        "<!-- keep me -->",
        "<img src=\"x.png\">",
        "~~~"
      ].join("\n")
    );
  });

  it("caps output at a block boundary and never splits a code fence", () => {
    const readme = [
      "First paragraph.",
      "",
      "```",
      "line one",
      "",
      "line two",
      "```",
      "",
      "Third paragraph that does not fit."
    ].join("\n");

    expect(cleanReadme(readme, 50)).toBe(
      ["First paragraph.", "", "```", "line one", "", "line two", "```"].join("\n")
    );
    expect(cleanReadme(readme, 20)).toBe("First paragraph.");
  });

  it("skips a single block larger than the cap and keeps filling after it", () => {
    const readme = ["Intro.", "", "x".repeat(80), "", "Outro."].join("\n");

    expect(cleanReadme(readme, 40)).toBe("Intro.\n\nOutro.");
  });

  it("unwraps relative links around inline code and keeps placeholders that are not HTML", () => {
    const readme = [
      "See [`docs/PRD.md`](docs/PRD.md) and [`ARCHITECTURE.md`](./ARCHITECTURE.md).",
      "Replace <your-api-key> before running."
    ].join("\n");

    expect(cleanReadme(readme)).toBe(
      "See `docs/PRD.md` and `ARCHITECTURE.md`.\nReplace <your-api-key> before running."
    );
  });

  it("returns an empty string for a badge-only or title-only README", () => {
    const badgeOnly = [
      "[![Build](https://img.shields.io/b.svg)](https://ci.example.com)",
      "<!-- nothing else -->"
    ].join("\n");

    expect(cleanReadme(badgeOnly)).toBe("");
    expect(cleanReadme("# Portfolio\n\n## About\n")).toBe("");
  });

  it("keeps footnote definitions while dropping link reference definitions", () => {
    const readme = ["Claim.[^1]", "", "[^1]: Source of the claim.", "[docs]: https://example.com"].join(
      "\n"
    );

    expect(cleanReadme(readme)).toBe("Claim.[^1]\n\n[^1]: Source of the claim.");
  });
});
